import * as THREE from 'three/webgpu';
import { color, uniform, mix, uv, vec3 } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'premium-pricing-card';
  const pos = config.scenePosition?.position || [0, 0, 0];
  const rot = config.scenePosition?.rotation || [0, 0, 0];
  const scl = config.scenePosition?.scale || [1, 1, 1];
  group.position.set(...pos);
  group.rotation.set(...rot);
  group.scale.set(...scl);

  const COLORS = {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    border: '#2a2a33',
    hairline: '#23232b',
    gradA: '#ff4450',
    gradB: '#c1121f',
  };

  const disposables = [];
  const timelines = [];

  const CARD_W = 2.4;
  const CARD_H = 3.2;
  const PAD = 0.5;
  const BASE = 0.25;

  // ---- Card backdrop ----
  const cardGeo = new THREE.PlaneGeometry(CARD_W, CARD_H);
  const cardMat = new THREE.MeshStandardNodeMaterial({
    colorNode: color(COLORS.surface),
    roughness: 0.6,
    metalness: 0.3,
  });
  disposables.push(cardGeo, cardMat);
  const card = new THREE.Mesh(cardGeo, cardMat);
  card.position.z = 0;
  group.add(card);

  // hairline border
  const borderGeo = new THREE.PlaneGeometry(CARD_W + 0.012, CARD_H + 0.012);
  const borderMat = new THREE.MeshBasicNodeMaterial({ colorNode: color(COLORS.border) });
  disposables.push(borderGeo, borderMat);
  const border = new THREE.Mesh(borderGeo, borderMat);
  border.position.z = -0.001;
  group.add(border);

  // ---- machined header strip ----
  const headerGeo = new THREE.PlaneGeometry(CARD_W, 0.08);
  const headerMat = new THREE.MeshStandardNodeMaterial({
    colorNode: color('#33333d'),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
  });
  headerMat.anisotropy = 0.6;
  disposables.push(headerGeo, headerMat);
  const header = new THREE.Mesh(headerGeo, headerMat);
  header.position.set(0, CARD_H / 2 - 0.04, 0.001);
  group.add(header);

  // specular band drag uniform
  const specPos = uniform(-1.0);
  headerMat.emissiveNode = mix(
    color('#000000'),
    color('#ffffff'),
    uv().x.sub(specPos).abs().oneMinus().clamp(0, 1).pow(8)
  );

  const topY = CARD_H / 2 - PAD;
  let cursorY = topY;

  // ---- tier name ----
  const tierText = ctx.fontAtlas.createText({
    text: 'ATELIER RESERVE',
    font: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 0.06,
    letterSpacing: 0.08,
    color: COLORS.paper,
  });
  tierText.position.set(-CARD_W / 2 + PAD, cursorY - 0.06, 0.002);
  group.add(tierText);
  cursorY -= 0.28;

  // ---- price ----
  const priceText = ctx.fontAtlas.createText({
    text: '$480',
    font: 'Lora',
    fontWeight: 600,
    fontSize: 0.19,
    letterSpacing: -0.01,
    color: COLORS.paper,
  });
  priceText.position.set(-CARD_W / 2 + PAD, cursorY - 0.19, 0.002);
  group.add(priceText);

  // caption on baseline
  const captionText = ctx.fontAtlas.createText({
    text: 'PER MONTH, BILLED ANNUALLY',
    font: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 0.028,
    letterSpacing: 0.12,
    color: '#8a8a94',
  });
  captionText.position.set(-CARD_W / 2 + PAD + 0.55, cursorY - 0.18, 0.002);
  group.add(captionText);

  cursorY -= 0.19 + 0.5; // 0.5 unit gap after price block

  // ---- feature rows ----
  const features = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing',
  ];
  const rowH = 0.375;
  const featureNodes = [];

  features.forEach((f, i) => {
    const rowTop = cursorY - i * rowH;
    const rowText = ctx.fontAtlas.createText({
      text: f,
      font: 'JetBrains Mono',
      fontWeight: 400,
      fontSize: 0.04,
      letterSpacing: 0,
      color: COLORS.paper,
    });
    rowText.position.set(-CARD_W / 2 + PAD, rowTop - 0.06, 0.002);
    rowText.userData.baseY = rowText.position.y;
    group.add(rowText);
    featureNodes.push(rowText);

    if (i > 0) {
      const hlGeo = new THREE.PlaneGeometry(CARD_W - PAD * 2, 0.006);
      const hlMat = new THREE.MeshBasicNodeMaterial({ colorNode: color(COLORS.hairline) });
      disposables.push(hlGeo, hlMat);
      const hl = new THREE.Mesh(hlGeo, hlMat);
      hl.position.set(0, rowTop + rowH / 2 - 0.19, 0.002);
      group.add(hl);
    }
  });

  // ---- CTA row ----
  const ctaW = 1.4, ctaH = 0.36;
  const ctaGeo = new THREE.PlaneGeometry(ctaW, ctaH);
  const ctaMat = new THREE.MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.2,
    emissive: new THREE.Color(COLORS.accent),
    emissiveIntensity: 1.5,
  });
  ctaMat.colorNode = mix(color(COLORS.gradA), color(COLORS.gradB), uv().y.oneMinus());
  disposables.push(ctaGeo, ctaMat);
  const cta = new THREE.Mesh(ctaGeo, ctaMat);
  cta.position.set(0, -CARD_H / 2 + 0.5, 0.003);
  group.add(cta);

  const ctaLabel = ctx.fontAtlas.createText({
    text: 'JOIN THE RESERVE',
    font: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 0.04,
    letterSpacing: 0.08,
    color: COLORS.ink,
    anchor: 'center',
  });
  ctaLabel.position.set(cta.position.x, cta.position.y, 0.004);
  group.add(ctaLabel);

  // ---- Animations ----
  group.scale.set(scl[0] * 1.04, scl[1] * 1.04, scl[2] * 1.04);
  const settleTl = gsap.timeline();
  settleTl.to(group.scale, {
    x: scl[0], y: scl[1], z: scl[2],
    duration: 0.9,
    ease: 'power4.out',
  });
  settleTl.to(specPos, { value: 2.0, duration: 0.9, ease: 'power4.out' }, 0);
  timelines.push(settleTl);

  featureNodes.forEach((n, i) => {
    n.position.y = n.userData.baseY - 0.2;
    if (n.material) n.material.transparent = true;
    n.traverse?.((c) => {
      if (c.material) { c.material.transparent = true; c.material.opacity = 0; }
    });
    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(n.position, { y: n.userData.baseY, duration: 0.5, ease: 'power2.out' });
    n.traverse?.((c) => {
      if (c.material) tl.to(c.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
    });
    timelines.push(tl);
  });

  // ---- CTA interaction ----
  const pressDown = () => {
    const tl = gsap.timeline();
    tl.to(cta.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
    timelines.push(tl);
  };
  const pressUp = () => {
    const tl = gsap.timeline();
    tl.to(cta.scale, { x: 1, y: 1, duration: 0.12, ease: 'back.out(1.7)' });
    timelines.push(tl);
  };

  group.userData.handlers = {
    onPointerDown: pressDown,
    onPointerUp: pressUp,
    onPointerOut: pressUp,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.forEach((d) => d.dispose && d.dispose());
    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose());
        else obj.material.dispose();
      }
    });
  };

  return group;
}
